// IQueryable -- deferred execution, builds an expression tree
IQueryable<Order> query = context.Orders.Where(o => o.Status == "Pending");
// No SQL has run yet -- query is just an expression tree at this point

query = query.Where(o => o.Amount > 1000);   // still building the expression tree
query = query.OrderByDescending(o => o.Amount);

var results = await query.ToListAsync();
// ONLY NOW does EF Core translate the full expression tree into ONE SQL query and execute it

// THE CLASSIC FOOTGUN -- calling ToList() too early forces in-memory filtering
var badResults = context.Orders.ToList()               // pulls ALL rows across the wire
    .Where(o => o.Status == "Pending")                   // filters in C#, not SQL!
    .Where(o => o.Amount > 1000);

// Correct version -- entire filter chain translates to SQL, only matching rows come back
var goodResults = await context.Orders
    .Where(o => o.Status == "Pending")
    .Where(o => o.Amount > 1000)
    .ToListAsync();

// Split query -- avoid Cartesian-product row explosion from multiple Includes
var ordersWithDetails = await context.Orders
    .Include(o => o.LineItems)
    .Include(o => o.StatusHistory)
    .AsSplitQuery()          // issues separate SQL queries per Include instead of one giant JOIN
    .ToListAsync();

// Compiled query -- pre-compiled translation for a very hot-path query
private static readonly Func<AppDbContext, int, Task<Order>> GetOrderById =
    EF.CompileAsyncQuery((AppDbContext ctx, int id) =>
        ctx.Orders.FirstOrDefault(o => o.Id == id));

var order = await GetOrderById(context, 12345);

// AsNoTrackingWithIdentityResolution -- read-only, but preserves object identity
var report = await context.Orders
    .Include(o => o.Customer)
    .AsNoTrackingWithIdentityResolution()
    .ToListAsync();
// If the same Customer appears via multiple Orders, all references point to the SAME
